import { useState } from 'react';

import './ProductPage.css'


function ProductPage({ addToCart }) {
  const [searchTerm, setSearchTerm] = useState('');

  const handleAddToCart = (product) => {
    addToCart(product);
    alert(`${product.name} has been added to your cart!`);
  };

  const [products] = useState([
    { id: 1, name: 'La Mousse Cleanser', brand: 'Chanel', price: 500,img: 'data:image/jpeg;base64,' },
    { id: 2, name: 'Serum De Beaute', brand: 'Gucci', price: 790, img: 'https://www.kunchals.in/cdn/shop/files/u_3616302937004_01.jpg?v=1735910822' },
    { id: 3, name: 'Powermatte Lipstick', brand: 'NARS', price: 500, img: 'https://cdn.fynd.com/v2/falling-surf-7c8bb8/fyprod/wrkr/products/pictures/item/free/original/000000000494284515/Y_ccWiDA0t-000000000494284515_1.png' },
    { id: 4, name: 'Weightless Foundation', brand: 'Bobbi Brown', price: 999, img: 'data:image/jpeg;base64,' },
    { id: 5, name: 'Demaquillant Yeux Intense', brand: 'Chanel', price: 890, img: 'data:image/jpeg;base64,' },
    { id: 6, name: 'Vitamin Cream', brand: 'Bobbi Brown', price: 1050, img: 'data:image/jpeg;base64,' },
    { id: 7, name: 'Flora Gorgeous Jasmine', brand: 'Gucci', price: 1200, img: 'data:image/jpeg;base64,' },
    { id: 8, name: 'Quad Eyeshadow', brand: 'NARS', price: 599, img: 'data:image/jpeg;base64,' },
    { id: 9, name: 'Lipstick', brand: 'Sugar', price: 790, img: 'data:image/jpeg;base64,' },
    { id: 10, name: 'City Stroke Eyeliner', brand: 'Mars', price: 200, img: 'https://images.meesho.com/images/products/398163636/kriok_1200.jpg' }
  ]);
    


  const filteredProducts = products.filter(product =>
    product.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    product.brand.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="product-page">
      <div className="product-header">
        <h1>Explore Our Shop</h1>
        <p>Discover luxury cosmetics crafted for your beauty and skincare needs.</p>
        <input
          type="text"
          placeholder="Search products..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="search-bar"
        />
      </div>

      <div className="product-grid">
        {filteredProducts.length > 0 ? (
          filteredProducts.map(product => (
            <div className="product-card" key={product.id}>
              <img src={product.img} alt={product.name} className="product-image" />
              <h3 className="product-name">{product.name}</h3>
              <p className="product-brand">{product.brand}</p>
              <p className="product-price">Rs.{product.price.toFixed(2)}</p>
              <button className="add-to-cart" onClick={() => handleAddToCart(product)}>
                Add to Cart
              </button>
            </div>
          ))
        ) : (
          <p>No products found.</p>
        )}
      </div>
    </div>
  );
}

export default ProductPage;
